import{_ as a,C as i,o as r,c as n,E as o,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Persistent Digital Employees Need Verification-Gated State Admission, Not Durable Memory Alone","description":"","frontmatter":{"title":"Persistent Digital Employees Need Verification-Gated State Admission, Not Durable Memory Alone","date":"2026-08-07","column":"digital-employee","category":"daily","summary":"A long-running Digital Employee must separate the history it preserves from the state allowed to shape future work: evidence can be append-only, while reusable memory, completion verdicts, and assurance projections require explicit admission authority.","item_id":"Q-20260807-01","source_research_object":"research/analysis/Q-20260807-01-verification-gated-durable-state-admission.md","source_reading_result":"research/reading/Q-20260807-01-argus-verification-gated-runtime.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-07-verification-gated-state-admission-cover-v2.jpg"},"headers":[],"relativePath":"en/digital-employee/2026-08-07-verification-gated-state-admission.md","filePath":"en/digital-employee/2026-08-07-verification-gated-state-admission.md","lastUpdated":1787407830000}'),d={name:"en/digital-employee/2026-08-07-verification-gated-state-admission.md"};function c(l,e,u,h,p,m){const t=i("ArticleCover");return r(),n("div",null,[o(t,{image:"/assets/covers/daily-2026-08-07-verification-gated-state-admission-cover-v2.jpg",kicker:"Digital Employee · Daily Research",title:"Persistent Digital Employees Need Verification-Gated State Admission, Not Durable Memory Alone",summary:"A long-running Digital Employee must separate the history it preserves from the state allowed to shape future work: evidence can be append-only, while reusable memory, completion verdicts, and assurance projections require explicit admission authority.",version:"Q-20260807-01",status:"Daily Runtime V5 · 2026-08-07",languageHref:"/zh/digital-employee/2026-08-07-verification-gated-state-admission",languageLabel:"中文"}),e[0]||(e[0]=s(' # Persistent Digital Employees Need Verification-Gated State Admission, Not Durable Memory Alone <p>Once a Digital Employee moves from a single interaction to long-running work, “remember more” is no longer a sufficient architecture. The hard question becomes: <strong>what should be preserved as history, and what has actually earned the right to influence the next mission?</strong></p><p>The same-day Research Object argues for a stricter separation. Provider sessions may be disposable, while work identity, evidence, accepted state, unresolved decisions, and completion provenance remain durable. But persistence and admission must not be the same operation.</p><h2 id="central-judgment" tabindex="-1">Central judgment <a class="header-anchor" href="#central-judgment" aria-label="Permalink to &quot;Central judgment&quot;">​</a></h2><p><strong>Durability is not authority.</strong></p><p>A model output, executor memory, reviewer judgment, or assurance object does not become future-runtime truth merely because it was written to disk. A persistent Digital Employee needs verification-gated state admission: preserve what happened first, then let evidence class and an explicit owner determine what may shape future work.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>This candidate consumes only the Production-authorized <code>Q-20260807-01</code> Research Object. Production did not return to the Signal Pool or the Reading Result to perform new research. The Reading Result appears only as the evidence boundary and provenance path declared by the Research Object.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>The Research Object distinguishes several durable surfaces: a long-lived campaign or work identity, an append-only event timeline, evidence references, checkpoints, open questions, memories and skills, routes, task definitions, completion verdicts, and derived assurance or certification views.</p><p>The important distinction is not which objects are stored. It is which objects acquire future influence. Failed attempts and rejected routes can remain durable because they may help a later pivot, but they should not be silently folded into a success narrative. A reviewer verdict can be retained as evidence without automatically becoming the authority that closes a consequential stage.</p><p>The object also preserves an instructive contradiction: canonical campaign completion and a stored assurance snapshot diverged, with the assurance view still blocked after the campaign itself had completed. That is a reminder that <strong>a durable projection can still be stale</strong>. A dashboard or automation that treats a persisted assurance object as canonical may let yesterday’s view override today’s state.</p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State surface</th><th>Primary purpose</th><th style="text-align:right;">Append-only?</th><th>Who may change future behavior?</th><th>Main risk</th></tr></thead><tbody><tr><td>Provider session</td><td>Temporary reasoning and tool context</td><td style="text-align:right;">No</td><td>It should not own long-term authority</td><td>Session loss and hidden context</td></tr><tr><td>Event and evidence history</td><td>Preserve what happened</td><td style="text-align:right;">Yes</td><td>History alone does not authorize reuse</td><td>Logged evidence remains unadjudicated</td></tr><tr><td>Reviewed checkpoint</td><td>Compact recovery surface</td><td style="text-align:right;">Versioned, not append-only</td><td>Policy-authorized owner</td><td>Omission or stale projection</td></tr><tr><td>Admitted reusable state</td><td>Define what future work may trust</td><td style="text-align:right;">Governed</td><td>Explicit owner + evidence gate</td><td>Bad memory becomes self-reinforcing</td></tr><tr><td>Assurance / certification projection</td><td>Operational or acceptance view</td><td style="text-align:right;">Recomputable</td><td>Must not override canonical workflow state</td><td>Stale projection becomes false authority</td></tr></tbody></table><p>The first four rows reflect mechanisms synthesized in the Research Object. “Admitted reusable state” is a Research Center engineering abstraction across those mechanisms, not a claim that the source implements a protocol object with that exact name.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>This reframes “Digital Employee memory” as a governance problem rather than a storage feature.</p><p>First, a long-running worker needs two durability promises: <strong>historical durability</strong> and <strong>authoritative durability</strong>. Historical durability preserves execution, failure, evidence, and role judgments for replay. Authoritative durability restricts future work to state that passed an admission decision. Combining both inside a single memory store quietly turns “recorded” into “trusted.”</p><p>Second, completion should remain a provenance-bearing verdict rather than the final sentence emitted by the worker. Low-risk, bounded work may permit policy-defined self-review. Higher-consequence transitions may require independent QA, EVAL, or operator/ADMIN approval. The architecture should not impose one universal reviewer; it should make visible who has authority to close which state transition.</p><p>Third, a checkpoint is a recovery optimization, not a replacement for the event trail. It can accelerate the next execution step, but it must remain reconcilable with the complete evidence chain. The same applies to assurance dashboards and certification summaries: they should be treated as projections that can be recalculated against canonical workflow state.</p><h2 id="engineering-impact" tabindex="-1">Engineering impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering impact&quot;">​</a></h2><p>For a Digital Employee runtime, model the long-lived unit as a WorkOrder or campaign identity that is independent from model sessions. Persist standing intent, current objective, constraints, verification criteria, and unresolved human decisions outside the provider transcript.</p><p>Maintain both an append-only execution/evidence tape and a smaller reviewed checkpoint used for recovery. Memory, skill, route, task-definition, and completion transitions should declare owners and evidence classes. Only admitted state should become an input to later missions.</p><p>For CodeFlowMu, FCoP-visible TASK/REPORT/REVIEW and event history should remain the shared fact surface while runtime checkpoints stay derived execution aids. Worker completion, QA verdict, EVAL observation, and ADMIN approval should not collapse into one boolean <code>done</code>. Recovery should resume from accepted state and unresolved decisions rather than requiring the original model session to survive.</p><h2 id="boundaries-and-counter-evidence" tabindex="-1">Boundaries and counter-evidence <a class="header-anchor" href="#boundaries-and-counter-evidence" aria-label="Permalink to &quot;Boundaries and counter-evidence&quot;">​</a></h2><p>The available evidence does not justify stronger claims. The reported startup-to-mature efficiency differences do not isolate the causal contribution of memory, review, routing, or task order. Independent Reviewer routing was not randomized and does not establish a universal false-acceptance rate. Verifier quality remains bounded by what the verifier can detect. And state admission cannot eliminate goal drift if the authorized decision-maker approves a poor tradeoff.</p><p>The defensible claim is therefore architectural: verification-gated admission improves the inspectability of what is allowed to persist as operational authority. It does not prove that durable memory always improves quality or that independent review is always superior.</p><h2 id="future-work" tabindex="-1">Future work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future work&quot;">​</a></h2><p>The next engineering question is a minimum admission contract that can distinguish proposed, evidenced, accepted, rejected, and superseded state. Different state classes should be tested against executable verification, independent QA, permitted self-review, and direct operator approval. Crash recovery also needs a transactional reconciliation strategy between canonical task state and derived assurance or checkpoint projections, plus prospective measurement of operator intervention and goal-drift correction.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The visual separates Transient Session, Append-only Evidence, Reviewed Checkpoint, State Admission, and Future Work, while showing Assurance as a recomputable side projection. It is a Research Center architecture synthesis based on the Research Object and contains no unsupported quantitative data.</p><h2 id="evidence-and-references" tabindex="-1">Evidence and references <a class="header-anchor" href="#evidence-and-references" aria-label="Permalink to &quot;Evidence and references&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260807-01-verification-gated-durable-state-admission.md" target="_blank" rel="noreferrer">Research Object — Verification-Gated Durable State Admission</a>: the sole analytical input, including observations, research judgment, uncertainty, counter-evidence, and engineering impact.</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260807-01-argus-verification-gated-runtime.md" target="_blank" rel="noreferrer">Reading Result — Argus verification-gated runtime</a>: the evidence boundary and provenance record declared by the Research Object; Production did not re-analyze this file.</li></ol>',33))])}const b=a(d,[["render",c]]);export{g as __pageData,b as default};
